    "_%n resolved report_::_%n resolved reports_" : ["%n rozpatrzone zgłoszenie","%n rozpatrzone zgłoszenia","%n rozpatrzonych zgłoszeń","%n rozpatrzonego zgłoszenia"],
    "Reported account" : "Zgłoszone konto",
    "Reporter" : "Zgłaszający",
